<script setup>
import {ref,computed,watch} from 'vue';
import BaseModal from './BaseModal.vue';
import AuditEvidence from './AuditEvidence.vue';
import AuditDocument from './AuditDocument.vue';
import {can,scope} from '../lib/workspace';
import {date,taxId} from '../lib/format';
const props=defineProps({document:Object,job:Object,busy:Boolean,error:String});
const emit=defineEmits(['close','auxiliary','link','treat']);
const tab=ref('document'),xml=ref(''),xmlError=ref(''),xmlBusy=ref(false),item=ref(null),itemSearch=ref('');
const normalized=computed(()=>props.document.normalized||{});
const booked=computed(()=>props.job.snapshot.bookkeeping.find(b=>b.id===props.document.bookkeeping_id));
const findings=computed(()=>props.job.findings.filter(f=>f.document_ref===props.document.document_ref));
const items=computed(()=>props.document.items.filter(i=>JSON.stringify(i).toLocaleLowerCase().includes(itemSearch.value.toLocaleLowerCase())));
const auxiliary=computed(()=>[...props.job.auxiliary.filter(a=>a.document_ref===props.document.document_ref).map(a=>({id:a.file_id,label:'PDF gerado do XML'})),...(props.document.auxiliary_file_ids||[]).map(id=>({id,label:'PDF original importado'})),...props.job.attachments.filter(a=>a.document_ref===props.document.document_ref).map(a=>({id:a.file_id,label:'PDF vinculado por '+a.created_by}))]);
const auxLabel=computed(()=>({'55':'DANFE','65':'DANFCE','57':'DACTE','58':'DAMDFE','67':'Espelho CT-e OS'}[props.document.model]||'Documento auxiliar'));
const sections=computed(()=>({document:'Documento',issuer:'Emitente',recipient:'Destinatário',items:`Produtos e serviços (${props.document.items.length})`,totals:'Totais',memory:'Auditoria e memória',transport:'Transporte',billing:'Cobrança',additional:'Informações adicionais',xml:'XML',auxiliary:auxLabel.value}));
const money=v=>v==null?'—':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const number=v=>v==null?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:6});
const fileUrl=(id,inline=false)=>`/api${scope(`/auditor/jobs/${props.job.id}/files?file_id=${id}${inline?'&inline=1':''}`)}`;
const keyValid=computed(()=>{const k=props.document.access_key||'';if(!/^\d{44}$/.test(k))return false;let sum=0,w=2;for(let i=42;i>=0;i--){sum+=Number(k[i])*w;w=w===9?2:w+1}const r=sum%11;return Number(k[43])===(r<2?0:11-r)});
watch(()=>props.document.document_ref,()=>{tab.value='document';xml.value='';xmlError.value='';item.value=null;itemSearch.value=''});
watch(tab,async value=>{if(value!=='xml'||xml.value||!can('auditor.analyses','export')||!props.document.original_file_id)return;xmlBusy.value=true;xmlError.value='';const ref=props.document.document_ref;try{const r=await fetch(fileUrl(props.document.original_file_id));if(!r.ok)throw Error('Não foi possível consultar o XML original.');const text=await r.text();if(props.document.document_ref===ref)xml.value=text.replace(/></g,'>\n<')}catch(e){xmlError.value=e.message}finally{xmlBusy.value=false}});
</script>
<template>
<BaseModal wide :title="`Documento ${document.number} · modelo ${document.model} · série ${document.series||'—'}`" :subtitle="job.snapshot.company.name+' · Auditoria #'+job.id+' · consulta somente leitura'" @close="emit('close')">
  <div class="inspection-head"><code>{{document.access_key||document.document_ref}}</code><span :class="['key-state',keyValid?'valid':'invalid']">{{keyValid?'Dígito verificador válido':'Chave ausente ou dígito inválido'}}</span></div>
  <div class="inspection-actions"><a v-if="document.original_file_id&&can('auditor.analyses','export')" class="button outline" :href="fileUrl(document.original_file_id)">Baixar XML original</a><span>Emissão {{date(document.issued_at)}} · {{document.direction==='entrada'?'Entrada':'Saída'}} · {{money(document.total_value)}}</span></div>
  <p v-if="error" class="message error" role="alert">{{error}}</p>
  <nav class="inspection-tabs" aria-label="Seções do documento fiscal"><button v-for="(label,key) in sections" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></nav>
  <div class="inspection-content">
    <section v-if="tab==='document'"><h3>Identificação e situação</h3><dl class="inspection-facts"><div><dt>Emitente</dt><dd>{{normalized.issuer?.name||normalized.issuer_name||'—'}}<small>{{taxId(document.issuer_tax_id)}}</small></dd></div><div><dt>Destinatário</dt><dd>{{normalized.recipient?.name||normalized.recipient_name||'—'}}<small>{{taxId(document.recipient_tax_id)}}</small></dd></div><div><dt>Origem</dt><dd>{{booked?'Escrituração #'+booked.id+' · versão '+booked.version:'Arquivos avulsos'}}</dd></div><div><dt>Data de escrituração</dt><dd>{{date(document.posting_date||booked?.posting_date)}}</dd></div></dl><AuditEvidence :value="normalized.identification"/><h3>Protocolo e eventos</h3><AuditEvidence :value="normalized.protocol"/><AuditEvidence v-if="normalized.cancellation_event" :value="normalized.cancellation_event"/><p class="hint">O protocolo informado é o conteúdo do XML; não constitui consulta atual à SEFAZ.</p></section>
    <section v-else-if="tab==='issuer'||tab==='recipient'"><h3>{{tab==='issuer'?'Dados do emitente':'Dados do destinatário'}}</h3><AuditEvidence :value="normalized[tab]||{}"/></section>
    <section v-else-if="tab==='items'"><label>Pesquisar produtos, NCM ou CFOP<input v-model="itemSearch" placeholder="Descrição, código, NCM…"/></label><div class="table-scroll"><table><thead><tr><th>Item</th><th>Produto / serviço</th><th>NCM / CFOP</th><th>Quantidade</th><th>Unitário</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="i in items" :key="i.item_number"><td>{{i.item_number}}</td><td><strong>{{i.description}}</strong><small>{{i.product_code}} · GTIN {{i.details?.ean_taxable||i.details?.ean||'—'}}</small></td><td>{{i.ncm}}<small>{{i.cfop}}</small></td><td>{{number(i.details?.quantity)}} {{i.details?.unit}}</td><td>{{money(i.details?.unit_value)}}</td><td>{{money(i.product_value)}}</td><td><button class="text-button" :aria-label="'Inspecionar item '+i.item_number" @click="item=i">Inspecionar</button></td></tr></tbody></table></div><p v-if="!items.length" class="hint">Nenhum item para os filtros ou modelo consultado.</p><section v-if="item" class="selected-item"><h3>Item {{item.item_number}} · {{item.description}}</h3><div class="inspection-facts"><div><small>Encontrado no XML</small><strong>{{item.actual_cst||'—'}} / {{item.actual_cclass_trib||'—'}}</strong></div><div><small>Esperado no catálogo</small><strong>{{item.expected_cst||'—'}} / {{item.expected_cclass_trib||'—'}}</strong></div><div><small>Situação</small><strong>{{item.classification_status}}</strong></div></div><h4>Tributos e componentes</h4><AuditEvidence :value="item.tax_components"/><h4>Rastreabilidade e informações adicionais</h4><AuditEvidence :value="item.details"/></section></section>
    <section v-else-if="tab==='totals'"><h3>Totais declarados no XML</h3><AuditEvidence :value="normalized.totals"/><div class="inspection-facts"><div><dt>Valor do documento</dt><dd>{{money(document.total_value)}}</dd></div><div><dt>Base IBS/CBS</dt><dd>{{money(document.ibs_cbs_base)}}</dd></div><div><dt>IBS</dt><dd>{{money(document.ibs_value)}}</dd></div><div><dt>CBS</dt><dd>{{money(document.cbs_value)}}</dd></div></div></section>
    <section v-else-if="tab==='memory'"><AuditDocument :document="document" :booked="booked" :findings="findings"/><h3>Achados deste documento</h3><article v-for="f in findings" :key="f.id" class="finding"><strong>{{f.rule_code}} · {{f.title}}</strong><p>{{f.description}}</p><AuditEvidence :value="f.evidence"/><p>{{f.recommended_action}}</p><button v-if="!job.deleted_at&&can('auditor.analyses','edit')" class="text-button" @click="emit('treat',f)">Registrar tratamento</button></article><p v-if="!findings.length">Nenhum achado vinculado a este documento.</p></section>
    <section v-else-if="tab==='transport'"><h3>Transporte e volumes</h3><AuditEvidence :value="normalized.transport"/></section>
    <section v-else-if="tab==='billing'"><h3>Fatura e cobrança</h3><AuditEvidence :value="normalized.billing"/><h3>Pagamentos</h3><div class="table-scroll"><table><thead><tr><th>Forma</th><th>Descrição</th><th>Valor</th></tr></thead><tbody><tr v-for="(p,n) in normalized.payments||[]" :key="n"><td>{{p.method||'—'}}</td><td>{{p.description||'—'}}</td><td>{{money(p.value)}}</td></tr></tbody></table></div><p v-if="!normalized.payments?.length">Sem grupo de pagamento informado no XML.</p></section>
    <section v-else-if="tab==='additional'"><h3>Informações adicionais</h3><AuditEvidence :value="normalized.additional_information"/><h3>Documentos referenciados</h3><AuditEvidence :value="normalized.identification?.references"/></section>
    <section v-else-if="tab==='xml'"><h3>XML fiscal original</h3><p v-if="!can('auditor.analyses','export')">A consulta do arquivo original exige permissão de exportação.</p><p v-else-if="!document.original_file_id">XML indisponível para este documento escriturado.</p><p v-else-if="xmlBusy">Carregando XML…</p><p v-else-if="xmlError" role="alert">{{xmlError}}</p><pre v-else class="xml-view">{{xml}}</pre></section>
    <section v-else-if="tab==='auxiliary'"><h3>{{auxLabel}}</h3><p class="hint">Representação visual; o XML permanece como fonte dos cálculos. {{document.model==='67'?'O espelho CT-e OS não equivale ao DACTE OS oficial.':''}}</p><div class="inspection-actions"><button v-if="document.original_file_id&&!job.deleted_at&&job.status==='completed'&&can('auditor.analyses','export')" class="button primary" :disabled="busy" @click="emit('auxiliary',document)">{{document.model==='55'?'Gerar DANFE':'Gerar documento auxiliar'}}</button><button v-if="!job.deleted_at&&can('auditor.analyses','edit')&&job.snapshot.files.some(f=>f.name.toLowerCase().endsWith('.pdf'))" class="button outline" @click="emit('link',document)">Vincular PDF importado</button></div><div v-for="a in auxiliary" :key="a.id"><p>{{a.label}} <a v-if="can('auditor.analyses','export')" class="button outline" :href="fileUrl(a.id,true)" target="_blank" rel="noopener">Abrir PDF auxiliar</a></p><iframe v-if="can('auditor.analyses','export')" :src="fileUrl(a.id,true)" :title="auxLabel+' · '+document.number" class="pdf-preview"/></div><p v-if="!auxiliary.length">Nenhum documento auxiliar armazenado. Gere a representação ou vincule um PDF importado.</p></section>
  </div>
  <template #footer><span class="hint">Esc fecha a consulta · a escrituração permanece inalterada</span><button class="button" @click="emit('close')">Fechar consulta</button></template>
</BaseModal>
</template>
<style scoped>
.inspection-head{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.inspection-head code{overflow-wrap:anywhere;font-size:12px}.key-state{font-size:11px;border-radius:12px;padding:4px 9px}.valid{background:#e2f1e8;color:#216447}.invalid{background:#fff0cf;color:#865710}.inspection-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:12px 0}.inspection-actions span{font-size:12px;color:#506b7e}.inspection-tabs{display:flex;gap:4px;overflow:auto;border-bottom:1px solid #d7e0e5;margin:18px 0}.inspection-tabs button{border:0;background:transparent;white-space:nowrap;padding:12px 10px;color:#587080}.inspection-tabs button.active{color:#225f57;border-bottom:3px solid #225f57;font-weight:700}.inspection-content{min-height:320px}.inspection-content h3{font-size:15px;margin:16px 0 12px}.inspection-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;background:#f3f6f8;border-radius:6px;padding:16px;margin:12px 0}.inspection-facts dt,small{font-size:11px;color:#617d8d;display:block}.inspection-facts dd{margin:5px 0;font-weight:600;overflow-wrap:anywhere}.selected-item,.finding{padding:16px;border:1px solid #d7e0e5;border-radius:7px;margin-top:16px}td{vertical-align:top}.xml-view{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f6;padding:16px;max-height:500px;overflow:auto;font-size:11px}.pdf-preview{width:100%;height:540px;border:1px solid #d7e0e5}.hint{color:#61798a;font-size:12px}@media(max-width:600px){.inspection-facts{grid-template-columns:1fr}.inspection-content{min-height:260px}}
</style>
